End KnowTests.

Section Sound.
Variable SEGS : list Segment.
Variable scfg : SpuriousCfg.
Variable A : atable.
Variable nx0 : nat.
Variable LIMIT : Z.
Hypothesis SEGS_wx : wx_segs_nowrap SEGS.
Hypothesis SEGS_in_hull : forall a : word, in_hull A (bv_unsigned a) = false -> find_segment SEGS (bv_unsigned a) 1 = None.

Definition res_len_okP : Prop := ltac2:(Rpl.RP.run_k (rplG ()) 0 "S1;A1;i2;A1;o1;Y6;00;A3;i4;i10;A2;k39;A2;i337;#0;#0;A1;k378;vSEGS;A1;k379;vA;").
Definition hull_okP : Prop := ltac2:(Rpl.RP.run_k (rplG ()) 0 "S3;A1;k380;vA;A1;o21;Y12;000;A1;k381;vA;A2;i30;A2;k16;o6;#0;A2;i30;A3;i4;i14;A2;k98;#0;#1;o6;A2;i30;A3;i4;i14;A2;k98;#2;#1;o6;A2;k16;#2;k382;").
Hypothesis RES_len : res_len_okP.
Hypothesis HULL_ok : hull_okP.
Variable SINV : env -> (word -> option byte) -> Prop.
Variable argH : env -> word -> bool.
Hypothesis argH_high : forall E (a : word), argH E a = true -> CEIL <= bv_unsigned a /\ uE E e_sp0 <= bv_unsigned a.
Hypothesis e_sp0_init : expr_vars_lt nx0 e_sp0 = true.
Hypothesis argH_agree : forall E E' (a : word), env_agree nx0 E E' -> argH E a = argH E' a.
Hypothesis SINV_frame : forall E M M', (forall a, argH E a = true -> M' a = M a) -> SINV E M -> SINV E M'.
Hypothesis SINV_agree : forall E E' M, env_agree nx0 E E' -> SINV E M -> SINV E' M.

Variable FS0 : Fs.Fs.

Definition segs_wr_ok : Prop := ltac2:(Rpl.RP.run_k (rplG ()) 0 "S0;Pseg;Ri210;P~RA3;k9;i210;r1;vSEGS;P~RA3;i4;i22;A1;k383;r2;o25;A3;i4;i22;A1;k384;r3;o25;").
Hypothesis SEGS_wr : segs_wr_ok.

#[local] Notation cfg := (cfg_of SEGS) (only parsing).
#[local] Notation CSOK := (cs_ok SEGS A LIMIT SINV argH FS0) (only parsing).
#[local] Notation HID := (hid A argH) (only parsing).
#[local] Notation MR := (Mr A argH) (only parsing).

#[local] Ltac aps_fill :=
  first [eassumption | exact (fun _ : nat => @None acs) | exact (fun _ _ _ => None) | exact (fun _ _ => None) | exact (fun _ => None)
        | exact 0%nat | exact 0%Z | exact nx0 | exact LIMIT].

Lemma w_reg_sound : forall E cs R FULL model n,
  CSOK E cs R FULL model -> (0 < n < 32)%nat -> getr R (Z_to_bv 5 (Z.of_nat n)) = edenot E (reg cs n).
Proof. ltac2:(Rpl.RP.run_k (rplG ()) 0 "S2;A1;i2;A1;o1;Y6;00;Y3;0;LE;Ri102;Lcs;Ri385;LR;RA2;k0;A1;o1;Y2;1;#0;LFULL;RP~R#0;A1;i15;A1;i2;A1;o1;#1;Lmodel;Ri386;Ln;Ri10;L~RA11;i387;vSEGS;vA;vLIMIT;vSINV;vargH;vFS0;r6;r5;r4;r3;r2;L~RA2;i30;A2;k134;o74;r2;A2;k134;r2;N32;A14;k388;vSEGS;vA;vLIMIT;vSINV;vargH;vFS0;r8;r7;r6;r5;r4;r3;r2;r1;").
Qed.

Lemma w_reg_lit_sound : forall E cs R FULL model n z,
  CSOK E cs R FULL model -> (0 < n < 32)%nat -> reg_lit cs n = Some z ->
  getr R (Z_to_bv 5 (Z.of_nat n)) = Z_to_bv 64 z /\ 0 <= z < two64.
